def validate_csv(csv_data):
    for line in csv_data.splitlines():
        parts = line.split(',')
        if len(parts) != 3:
            return False
        try:
            float(parts[2].strip())  # Check if price is a valid float
        except ValueError:
            return False
    return True

# Example usage
csv_data = "item1,description1,10.5\nitem2,description2,20.0"
print(validate_csv(csv_data))  # Should print True
